import{z as n,x as i,o,c as A,q as B,j as l,D as E,d as e,s,S as d,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"影子栈与 CET","description":"","frontmatter":{"title":"影子栈与 CET","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/shadow-stack-cet.md","filePath":"cs/shadow-stack-cet.md","lastUpdated":1791413859000}'),c={name:"cs/shadow-stack-cet.md"};function p(C,a,T,h,D,m){const r=i("Mermaid");return o(),A("div",null,[a[2]||(a[2]=B('<h1 id="影子栈与-cet" tabindex="-1">影子栈与 CET <a class="header-anchor" href="#影子栈与-cet" aria-label="Permalink to &quot;影子栈与 CET&quot;">​</a></h1><div class="epigraph"><p>影子栈把返回地址放进攻击者默认不可写的第二份栈；CET 再给间接跳加「合法目标」标记。硬件把 CFI 从编译器希望变成页表与指令集合同。</p><footer>—— Intel CET 白皮书；对照 Abadi CFI；Microsoft 对 HW-enforced stack protection 的陈述</footer></div><p>上一课<a href="/cs/type-confusion">类型混淆</a>的落点仍可能是改函数指针。缺口是<strong>硬件协助的控制流完整性</strong>：影子栈与间接分支跟踪（IBT）。本课不重写 ROP 定义，只补：控制流合同为何不能只靠软件自觉，要落到页表与指令集。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>软件 CFI 在每个间接跳前插检查，但检查同在进程内存里——攻击者拿到任意写，检查可被改写或跳过。硬件版把两份合同搬进任意写够不着的层。影子栈：<code>call</code> 把返回地址同压两份栈，<code>ret</code> 核对，不匹配即异常——ROP 靠改栈上返回地址串联，从此必被抓住。IBT：间接跳与间接调用只许落在 <code>endbr</code> 一类着陆点，落到 gadget 中部即 fault。剩下的缺口在覆盖：哪些库与 JIT 代码进了合同，旧二进制如何兼容。</p><h3 id="不是内存安全" tabindex="-1">不是内存安全 <a class="header-anchor" href="#不是内存安全" aria-label="Permalink to &quot;不是内存安全&quot;">​</a></h3><p>这不是内存安全：任意写仍在，数据面的指针与长度字段照样能改。变的只是返回与部分间接边：从「希望没被改」到「改了必被抓住」。</p><p><span class="marginnote">Intel CET。ARM 有 PAC（下一课）与 BTI。本课不写绕过 CET 的步骤。</span></p><p><span class="marginnote">直觉类比：影子栈像把返回地址另抄一份锁进保险柜——主栈随便被翻动，<code>ret</code> 时先开保险柜核对，对不上就报警。攻击者即便能改主栈，也摸不到保险柜：那份副本由独立页表权限看守，任意写默认够不着。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照软件影子栈与硬件版：合同相同，托管运行时早已软件实现，硬件把核对挪进微码与页表权限。两个工程落点：JIT 代码必须显式发 <code>endbr</code>，否则合法间接跳被误杀；CET 与 ASLR 叠加——IBT 先压缩可用 gadget 集，ASLR 再让可达位置随机。下一课 PAC：签指针本身。</p><p><span class="marginnote">数字实例：一条典型 ROP gadget 只有几条指令（十来个字节量级），且可从任意指令边界起跳；IBT 生效后，间接跳只许落在 <code>endbr</code> 标记处，可用「跳板」从全部指令边界收缩到编译器显式点名的位置——可拼链条数直接掉几个数量级，ASLR 再给剩下那点雪上加霜。</span></p>',13)),(o(),l(d,null,{default:E(()=>[s(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22call%22%5D%20--%3E%20SS%5B%22%E5%BD%B1%E5%AD%90%E6%A0%88%E5%AD%98%E8%BF%94%E5%9B%9E%E5%9C%B0%E5%9D%80%22%5D%0A%20%20RET%5B%22ret%22%5D%20--%3E%20CMP%5B%22%E4%B8%8E%E5%BD%B1%E5%AD%90%E6%A0%88%E6%A0%B8%E5%AF%B9%22%5D%0A%20%20IJ%5B%22%E9%97%B4%E6%8E%A5%E8%B7%B3%22%5D%20--%3E%20ENDBR%5B%22%E9%A1%BB%E8%90%BD%E5%88%B0%E5%90%88%E6%B3%95%E7%9D%80%E9%99%86%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("机制的转变是把控制边当一等对象由硬件看管：返回边靠影子副本核对，间接边靠着陆点白名单，两份核对都在任意写够不着的层执行，不再依赖「攻击者恰好没改检查」这一软件 CFI 软肋。代价随之清楚：影子栈要独立存储与切换语义（信号、协程要接住），IBT 对缺 "),t("code",null,"endbr"),e(" 的旧代码是可用性风险。下一课指针认证换一条路：签名放进指针高位，改指针要过密钥——从看管边到看管指针。")],-1)),(o(),l(d,null,{default:E(()=>[s(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E6%94%BB%E5%87%BB%E8%80%85%E8%8E%B7%E5%BE%97%E4%BB%BB%E6%84%8F%E5%86%99%22%5D%20--%3E%20Q1%7B%22%E7%AF%A1%E6%94%B9%E6%A0%88%E4%B8%8A%E8%BF%94%E5%9B%9E%E5%9C%B0%E5%9D%80%3F%22%7D%0A%20%20Q1%20--%3E%7C%E6%98%AF%7C%20SS%5B%22ret%20%E6%97%B6%E4%B8%8E%E5%BD%B1%E5%AD%90%E6%A0%88%E6%A0%B8%E5%AF%B9%22%5D%0A%20%20SS%20--%3E%20X1%5B%22%E4%B8%8D%E5%8C%B9%E9%85%8D%E8%A7%A6%E5%8F%91%E5%BC%82%E5%B8%B8%2C%20ROP%20%E9%93%BE%E6%96%AD%22%5D%0A%20%20Q1%20--%3E%7C%E5%90%A6%E5%88%99%7C%20Q2%7B%22%E9%97%B4%E6%8E%A5%E8%B7%B3%E5%88%B0%20gadget%20%E4%B8%AD%E9%83%A8%3F%22%7D%0A%20%20Q2%20--%3E%7C%E6%98%AF%7C%20IBT%5B%22%E7%9B%AE%E6%A0%87%E4%B8%8D%E6%98%AF%20endbr%20%E7%9D%80%E9%99%86%E7%82%B9%22%5D%0A%20%20IBT%20--%3E%20X2%5B%22%E6%8C%87%E4%BB%A4%20fault%2C%20%E6%8E%A7%E5%88%B6%E6%B5%81%E8%A2%AB%E6%8B%92%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p><span class="marginnote">常见误区：初学者容易把 CET 当成内存安全的代名词。任意写依旧存在——数据指针、缓冲区长度照样能改；CET 只锁「控制流转移边」这两类，改动数据面的漏洞它一概不管，所以要和 ASLR、类型安全语言分层叠加。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给关闭或绕过 CET 的利用步骤；软件影子栈与硬件启用的平台差异只作定性。PAC 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>类型混淆仍要改控制数据；CET 让返回/间接跳变硬。</li><li>影子栈核对返回；IBT 限制着陆点。</li><li>覆盖率取决于编译与 JIT。</li><li>下一课指针认证 PAC。</li><li>出处：Intel CET；Abadi et al.；对照 ARM BTI。</li></ul>',5))])}const _=n(c,[["render",p]]);export{u as __pageData,_ as default};
